from taf.ul.auto_commissioning.injector import Injector
from taf.ul.auto_commissioning.generator.generator import PyDeltaGenerator


class auto_commissioning(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def generate_json_delta(self, base_scf_addr, custom_scf_addr, json_addr):
        """
        Creates delta in JSON format. Delta is composed of 3 lists of objects:
        - Managed Objects added (present in custom scf, but not in base scf)
        - Managed Objects removed (present in base scf, but not in custom scf)
        - Managed Objects changed (present in base and custom scf, but they differ)

        There are assumptions made on SCF schema that enable generating delta:

        # Managed objects and distanmes are not duplicated

        # List can have multiple Items

        # Params declared directly in Lists are always nameless

        # Params can have empty values

        # Nameless params are only possible directly in a List

        # Each distname of Managed Object in SCF has positive digit correlating to name of each object.:
        e.g. MRBTS-100/MNL-2/WHATEVER-1/SMTH-2


        Note on MRBTS Ids:
        MRBTS ID of each Managed Object is ignored in comparison of base and custom SCF.
        It implies that Managed Objects with distnames that differ only by MRBTS-ID are considered the same
        (also NOT CHANGED if all other qualities of said Managed Objects are the same - CHANGED otherwise).

        :param base_scf_addr: source SCF which custom made SCF is based on.
        :param custom_scf_addr: finished SCF
        :param json_addr: JSON delta file address
        :return:
        """
        PyDeltaGenerator(base_scf=base_scf_addr, full_scf=custom_scf_addr).generate_into_json(json_addr=json_addr)

    def inject_json_delta(self, scf_object, json_addr):
        """
        Uses delta SCF to inject it into object of taf.internal.scf
        Injected Managed Objects will have MRBTS-ID of taf.internal.scf object

        :param scf_object: taf.internal.scf instance
        :param json_addr: json delta file address
        :return:
        """
        Injector(scf_object).inject_json_delta(json_addr)
